// --- Review Card ---
interface ReviewCardProps {
    title: string;
    subtitle?: string;
    rating?: number;
    text: string;
    date: string;
    avatar?: string;
    imageUrl?: string;
    likes: number;
    comments: number;
    tags?: string[];
    isScam?: boolean;
    onClick?: () => void;
}

export const ReviewCard: React.FC<ReviewCardProps> = ({ 
    title, subtitle, rating, text, date, avatar, imageUrl, likes, comments, tags, isScam, onClick 
}) => {
    return (
        <div 
            onClick={onClick}
            className="bg-white dark:bg-surface-dark rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-800 hover:shadow-md transition-shadow cursor-pointer relative overflow-hidden"
        >
            {isScam && (
                <div className="absolute top-0 right-0 w-16 h-16 bg-gradient-to-bl from-red-500/10 to-transparent rounded-bl-full -mr-8 -mt-8 pointer-events-none"></div>
            )}

            <div className="flex items-start justify-between mb-2">
                <div className="flex gap-3 w-full">
                    {/* Avatar/Icon Area */}
                    <div className={`h-12 w-12 rounded-xl flex items-center justify-center shrink-0 overflow-hidden ${isScam ? 'bg-red-50 dark:bg-red-900/20 text-red-500' : 'bg-gray-100 dark:bg-gray-700'}`}>
                        {avatar ? (
                            <img src={avatar} alt={title} className="h-full w-full object-cover" />
                        ) : isScam ? (
                            <Icon name="phone_disabled" size={24} />
                        ) : (
                             <Icon name="storefront" className="text-gray-400" />
                        )}
                    </div>

                    {/* Header Content */}
                    <div className="flex-1 min-w-0">
                        <div className="flex justify-between items-start">
                            <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-tight truncate pr-2">{title}</h3>
                            {tags && tags.length > 0 && (
                                <span className={`inline-flex items-center rounded-md px-2 py-1 text-xs font-medium ring-1 ring-inset shrink-0 ${isScam ? 'bg-red-50 text-red-600 ring-red-500/20' : 'bg-green-50 text-green-700 ring-green-600/20'}`}>
                                    {tags[0]}
                                </span>
                            )}
                        </div>

                        <div className="flex items-center gap-1 mt-0.5">
                            {isScam ? (
                                <>
                                    <Icon name="warning" className="text-red-500" size={18} />
                                    <span className="text-sm font-medium text-red-600 dark:text-red-400">High Risk</span>
                                </>
                            ) : (
                                <>
                                    {rating && (
                                        <>
                                            <Icon name="star" filled className="text-amber-400" size={18} />
                                            <span className="text-sm font-semibold text-slate-900 dark:text-white">{rating}</span>
                                        </>
                                    )}
                                    {subtitle && <span className="text-xs text-gray-500 dark:text-gray-400 ml-1">• {subtitle}</span>}
                                </>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed line-clamp-2 mb-3">
                {isScam && <span className="font-semibold text-red-500">Warning: </span>}
                {text}
            </p>

            <div className="flex items-center justify-between border-t border-gray-100 dark:border-gray-700/50 pt-3 mt-1">
                <div className="flex items-center gap-4">
                    <button className={`flex items-center gap-1.5 transition-colors group ${isScam ? 'text-primary' : 'text-gray-500 hover:text-primary'}`}>
                        <Icon name="thumb_up" filled={isScam} size={18} className="group-hover:text-primary" />
                        <span className="text-xs font-medium">{likes} {isScam ? 'found helpful' : ''}</span>
                    </button>
                    {!isScam && (
                        <button className="flex items-center gap-1.5 text-gray-500 hover:text-blue-500 transition-colors">
                            <Icon name="chat_bubble" size={18} />
                            <span className="text-xs font-medium">{comments}</span>
                        </button>
                    )}
                </div>
                <span className="text-xs text-gray-400">{date}</span>
            </div>
        </div>
    );
};

// --- Bottom Nav ---
export const BottomNav = ({ activeTab, onNavigate }: { activeTab: string, onNavigate: (v: any) => void }) => {
    const navItems = [
        { id: 'HOME', icon: 'home', label: 'Home' },
        { id: 'SEARCH', icon: 'search', label: 'Search' },
        { id: 'ADD', icon: 'add', label: '', isFab: true },
        { id: 'SAVED', icon: 'favorite', label: 'Saved' },
        { id: 'PROFILE', icon: 'person', label: 'Profile' },
    ];

    return (
        <nav className="fixed bottom-0 left-0 right-0 w-full bg-white dark:bg-background-dark border-t border-gray-100 dark:border-gray-800 pb-safe z-40 max-w-md mx-auto">
             {/* iOS Home Indicator Safe Area spacing handled by pb-safe if set in CSS, here simulated via padding */}
            <div className="flex justify-around items-center h-16 px-2 pb-2">
                {navItems.map((item) => {
                    if (item.isFab) {
                        return (
                            <div key={item.id} className="-mt-8 relative z-50">
                                <button 
                                    onClick={() => onNavigate('WRITE_REVIEW_MODAL')}
                                    className="h-14 w-14 rounded-full bg-primary text-white shadow-lg shadow-primary/30 flex items-center justify-center hover:bg-primary-dark transition-transform active:scale-95"
                                >
                                    <Icon name={item.icon} size={28} />
                                </button>
                            </div>
                        );
                    }
                    const isActive = activeTab === item.id;
                    return (
                        <button 
                            key={item.id}
                            onClick={() => onNavigate(item.id)}
                            className={`flex flex-col items-center justify-center w-full h-full gap-1 transition-colors ${isActive ? 'text-primary' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}
                        >
                            <Icon name={item.icon} filled={isActive} size={26} />
                            <span className="text-[10px] font-medium">{item.label}</span>
                        </button>
                    );
                })}
            </div>
        </nav>
    );
};

