import React, { useState } from 'react';
import { ViewState, Review } from './types';
import { Splash } from './pages/Splash';
import { Home } from './pages/Home';
import { Search } from './pages/Search';
import { ReviewDetails } from './pages/ReviewDetails';
import { Profile } from './pages/Profile';
import { MyReviews } from './pages/MyReviews';
import { WriteReviewModal } from './pages/WriteReviewModal';
import { Verify } from './pages/Verify';
import { BottomNav } from './components/Shared';

const App = () => {
  const [view, setView] = useState<ViewState>('SPLASH');
  const [selectedReview, setSelectedReview] = useState<Review | null>(null);
  const [showWriteModal, setShowWriteModal] = useState(false);

  const navigate = (newView: string, data?: any) => {
    // Handle specific modal triggers
    if (newView === 'WRITE_REVIEW_MODAL') {
        setShowWriteModal(true);
        return;
    }

    // Simple routing logic
    if (newView === 'REVIEW_DETAILS' && data) {
        setSelectedReview(data);
    }

    setView(newView as ViewState);
    window.scrollTo(0, 0);
  };

  const renderView = () => {
    switch (view) {
      case 'SPLASH':
        return <Splash navigate={navigate} />;
      case 'HOME':
        return <Home navigate={navigate} onReviewClick={(r) => navigate('REVIEW_DETAILS', r)} />;
      case 'SEARCH':
        return <Search navigate={navigate} onReviewClick={(r) => navigate('REVIEW_DETAILS', r)} />;
      case 'REVIEW_DETAILS':
        return <ReviewDetails review={selectedReview} navigate={navigate} />;
      case 'PROFILE':
        return <Profile navigate={navigate} />;
      case 'MY_REVIEWS':
        return <MyReviews navigate={navigate} onReviewClick={(r) => navigate('REVIEW_DETAILS', r)} />;
      case 'VERIFY':
        return <Verify navigate={navigate} />;
      default:
        return <Home navigate={navigate} onReviewClick={(r) => navigate('REVIEW_DETAILS', r)} />;
    }
  };

  // Nav is shown on Home, Profile, and My Reviews (Top level tabs)
  // Search is now treated as a sub-page, so nav is hidden
  const showNav = ['HOME', 'PROFILE', 'MY_REVIEWS'].includes(view);

  return (
    <div className="max-w-md mx-auto bg-white dark:bg-background-dark min-h-screen relative shadow-2xl overflow-hidden">
      {renderView()}

      {showNav && (
        <BottomNav 
            activeTab={view} 
            onNavigate={(id) => {
                if (id === 'ADD') {
                     setShowWriteModal(true);
                } else {
                     navigate(id);
                }
            }} 
        />
      )}

      {showWriteModal && <WriteReviewModal onClose={() => setShowWriteModal(false)} />}
    </div>
  );
};

